import type { Metadata } from 'next';
import { GoogleFont } from '@/types/pillar';
import './globals.css';

export const metadata: Metadata = {
  title: 'Carousel Generator',
  description: 'Generate beautiful social media carousels with pillar-specific theming',
};

// Collect all unique Google Fonts from all pillar themes
const allGoogleFonts: GoogleFont[] = [
  { family: 'Cinzel', weights: [400, 700, 900] },
  { family: 'Inter', weights: [300, 400, 600, 700, 900] },
  { family: 'JetBrains Mono', weights: [400, 600, 700] },
  { family: 'Georgia', weights: [400, 700] },
  { family: 'Playfair Display', weights: [400, 700, 900] },
  { family: 'Lato', weights: [300, 400, 700] },
];

// Generate Google Fonts URL
const generateGoogleFontsUrl = (fonts: GoogleFont[]): string => {
  const fontParams = fonts
    .map(font => `${font.family.replace(' ', '+')}:wght@${font.weights.join(';')}`)
    .join('&');
  return `https://fonts.googleapis.com/css2?family=${fontParams}&display=swap`;
};

const googleFontsUrl = generateGoogleFontsUrl(allGoogleFonts);

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <head>
        <link rel="preconnect" href="https://fonts.googleapis.com" />
        <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="" />
        <link href={googleFontsUrl} rel="stylesheet" />
      </head>
      <body className="antialiased">{children}</body>
    </html>
  );
}